function num(value: unknown): number {
  const parsed = Number(value ?? 0);
  return Number.isFinite(parsed) ? parsed : 0;
}

function safeRate(numerator: number, denominator: number): number {
  return denominator > 0 ? numerator / denominator : 0;
}

function dateInTimezone(date = new Date(), timezone = "Asia/Kolkata") {
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone: timezone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(date);
  const get = (type: string) => parts.find((part) => part.type === type)?.value || "";
  return `${get("year")}-${get("month")}-${get("day")}`;
}

function addDays(date: string, days: number) {
  const current = new Date(`${date}T00:00:00+05:30`);
  current.setUTCDate(current.getUTCDate() + days);
  return dateInTimezone(current, "Asia/Kolkata");
}

function previousWindow(startDate: string, endDate: string) {
  const start = new Date(`${startDate}T00:00:00+05:30`);
  const end = new Date(`${endDate}T00:00:00+05:30`);
  const days = Math.max(1, Math.round((end.getTime() - start.getTime()) / 86400000) + 1);
  const previousEnd = addDays(startDate, -1);
  const previousStart = addDays(previousEnd, -(days - 1));
  return { start_date: previousStart, end_date: previousEnd };
}

function apiCandidates(path: string) {
  const base = (process.env.BASE_INTERNAL_URL || process.env.BASE_URL || "").replace(/\/+$/, "");
  if (!base) throw new Error("BASE_INTERNAL_URL or BASE_URL is required to read dashboard datatables.");
  const normalized = path.startsWith("/") ? path : `/${path}`;
  if (base.endsWith("/api")) return [`${base}${normalized}`];
  return [`${base}/api${normalized}`, `${base}${normalized}`];
}

async function apiPost(path: string, body: unknown) {
  const token = process.env.WM_TOKEN;
  if (!token) throw new Error("WM_TOKEN is required to read dashboard datatables.");
  let lastError = "";
  for (const candidate of apiCandidates(path)) {
    const response = await fetch(candidate, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify(body),
    });
    if (response.ok) return await response.json();
    lastError = `${response.status} ${await response.text().catch(() => "")}`;
    if (response.status !== 404) break;
  }
  throw new Error(`Windmill API request failed for ${path}: ${lastError}`);
}

function datatable(workspace: string) {
  return (strings: TemplateStringsArray, ...values: unknown[]) => {
    const args = Object.fromEntries(values.map((value, index) => [`arg${index + 1}`, value]));
    const comments = values.map((_, index) => `-- $${index + 1} arg${index + 1}`).join("\n");
    const placeholder = (value: unknown, nextChunk: string, index: number) => {
      if (nextChunk.trimStart().startsWith("::")) return `$${index + 1}`;
      if (typeof value === "number") return Number.isInteger(value) ? `$${index + 1}::BIGINT` : `$${index + 1}::DOUBLE PRECISION`;
      if (typeof value === "boolean") return `$${index + 1}::BOOLEAN`;
      if (value === null || value === undefined || typeof value === "string") return `$${index + 1}::TEXT`;
      return `$${index + 1}::JSONB`;
    };
    const content = strings.reduce((query, chunk, index) => {
      return query + chunk + (index < values.length ? placeholder(values[index], strings[index + 1], index) : "");
    }, comments ? `${comments}\n\n` : "");

    const run = () =>
      apiPost(`/w/${workspace}/jobs/run_inline/preview`, {
        language: "postgresql",
        content,
        args: { ...args, database: "datatable://main" },
      });

    return {
      fetch: run,
      async fetchOne() {
        const rows = await run();
        return Array.isArray(rows) ? rows[0] : rows;
      },
    };
  };
}

async function tableExists(sql: ReturnType<typeof datatable>, tableName: string) {
  const row = await sql`
    SELECT EXISTS (
      SELECT 1
      FROM information_schema.tables
      WHERE table_schema = 'public'
        AND table_name = ${tableName}
    ) AS exists
  `.fetchOne();
  return Boolean(row?.exists);
}

function summarize(rows: DailyRow[]) {
  const spend = rows.reduce((sum, row) => sum + num(row.spend), 0);
  const reach = rows.reduce((sum, row) => sum + num(row.reach), 0);
  const impressions = rows.reduce((sum, row) => sum + num(row.impressions), 0);
  const linkClicks = rows.reduce((sum, row) => sum + num(row.link_clicks), 0);
  const websiteVisits = rows.reduce((sum, row) => sum + num(row.website_visits), 0);
  const typeformSubmits = rows.reduce((sum, row) => sum + num(row.typeform_submits), 0);
  const shares = rows.reduce((sum, row) => sum + num(row.shares), 0);
  const comments = rows.reduce((sum, row) => sum + num(row.comments), 0);
  const frequency = safeRate(rows.reduce((sum, row) => sum + num(row.frequency) * num(row.reach), 0), reach);
  return {
    spend,
    reach,
    impressions,
    link_clicks: linkClicks,
    website_visits: websiteVisits,
    typeform_submits: typeformSubmits,
    shares,
    comments,
    frequency,
    ctr: safeRate(linkClicks, impressions),
    cpc: safeRate(spend, linkClicks),
    cpm: impressions > 0 ? (spend / impressions) * 1000 : 0,
    cpl: typeformSubmits > 0 ? spend / typeformSubmits : null,
    click_rate: safeRate(linkClicks, reach),
    website_visit_rate: safeRate(websiteVisits, linkClicks),
    typeform_submit_rate: safeRate(typeformSubmits, websiteVisits),
  };
}

function groupBy<T>(rows: T[], getKey: (row: T) => string | undefined) {
  const groups = new Map<string, T[]>();
  for (const row of rows) {
    const key = getKey(row) || "unknown";
    groups.set(key, [...(groups.get(key) || []), row]);
  }
  return groups;
}

function delta(current: number | null, previous: number | null, lowerIsBetter = false) {
  if (current === null || previous === null || previous === 0) return { value: null, good: null };
  const value = (current - previous) / previous;
  const good = lowerIsBetter ? value <= 0 : value >= 0;
  return { value, good };
}

function dailySeries(rows: DailyRow[], metric: string) {
  return [...groupBy(rows, (row) => String(row.metric_date).slice(0, 10)).entries()]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([date, dayRows]) => {
      if (metric === "daily_cpl") {
        const totals = summarize(dayRows);
        return { date, value: totals.typeform_submits > 0 ? totals.spend / totals.typeform_submits : 0 };
      }
      return { date, value: dayRows.reduce((sum: number, row: any) => sum + num(row[metric]), 0) };
    });
}

function campaignStatus(current: any, previous: any, accountCpl: number | null) {
  const cplOk = accountCpl !== null && current.cpl !== null && current.cpl <= accountCpl;
  const ctrDeclining = previous?.ctr ? current.ctr < previous.ctr * 0.85 : false;
  const cplIncreasing = previous?.cpl && current.cpl ? current.cpl > previous.cpl * 1.15 : false;
  if (cplOk && current.typeform_submits >= 2) return "Scale";
  if (current.spend > 1000 && current.typeform_submits === 0) return "Weak";
  if (current.frequency > 3 && ctrDeclining) return "Fatigue";
  if (ctrDeclining || cplIncreasing) return "Watch";
  return "Healthy";
}

function buildInsights(totals: any, previous: any) {
  const insights: Array<{ title: string; body: string; tone: string }> = [];
  if (totals.ctr < 0.008) insights.push({ title: "Creative needs a stronger hook", body: "CTR is below 0.8%. Refresh the first frame, headline, or offer clarity.", tone: "amber" });
  if (totals.website_visits > 0 && safeRate(totals.typeform_submits, totals.website_visits) < 0.02) insights.push({ title: "Landing page conversion is light", body: "Website visits are not converting into Typeform submits strongly enough.", tone: "pink" });
  if (totals.typeform_submits > previous.typeform_submits && totals.cpl !== null && previous.cpl !== null && totals.cpl < previous.cpl) insights.push({ title: "Scale signal", body: "Typeform submits increased while CPL decreased versus the previous period.", tone: "green" });
  if (previous.reach > 0 && totals.reach < previous.reach * 0.8) insights.push({ title: "Reach dropped", body: "Reach dropped more than 20% versus the previous period. Check budgets and delivery.", tone: "amber" });
  if (totals.shares > 0) insights.push({ title: "Content resonance", body: "Top creatives are generating shares. Use these themes for the next creative batch.", tone: "blue" });
  return insights.length ? insights.slice(0, 5) : [{ title: "No major alerts", body: "The account does not show a sharp funnel break in this period.", tone: "green" }];
}

function money(value: number | null) {
  if (value === null || !Number.isFinite(value)) return "n/a";
  return `Rs ${Math.round(value).toLocaleString("en-IN")}`;
}

function integer(value: number) {
  return Math.round(value).toLocaleString("en-IN");
}

function pct(value: number) {
  return `${(value * 100).toFixed(value === 0 || Math.abs(value) >= 0.1 ? 1 : 2)}%`;
}

function escapeHtml(value: unknown) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

function statusClass(status: string) {
  return status.toLowerCase().replace(/[^a-z0-9]+/g, "-");
}

function normalizeQuery(query: Record<string, string> | null | undefined) {
  const today = dateInTimezone(new Date(), "Asia/Kolkata");
  const endDate = /^\d{4}-\d{2}-\d{2}$/.test(String(query?.end_date || "")) ? String(query?.end_date) : today;
  const startDate = /^\d{4}-\d{2}-\d{2}$/.test(String(query?.start_date || "")) ? String(query?.start_date) : addDays(endDate, -6);
  return { startDate, endDate };
}

function decodeBase64(value: string) {
  const binary = atob(value);
  const bytes = Uint8Array.from(binary, (char) => char.charCodeAt(0));
  return new TextDecoder().decode(bytes);
}

function renderRawAppHtml() {
  const css = decodeBase64(RAW_APP_CSS_BASE64);
  const js = decodeBase64(RAW_APP_JS_BASE64);
  return `<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Beforest Facebook Ads Growth Dashboard</title>
    <style>${css}</style>
  </head>
  <body>
    <div id="root"></div>
    <script>
      window.wmill = {
        backend: {
          fetch_dashboard: async function(args) {
            var url = new URL(window.location.href);
            url.searchParams.set(${JSON.stringify(RAW_APP_API_PARAM)}, "fetch_dashboard");
            if (args && args.start_date) url.searchParams.set("start_date", args.start_date);
            if (args && args.end_date) url.searchParams.set("end_date", args.end_date);
            var response = await fetch(url.toString(), { headers: { "Accept": "application/json" } });
            if (!response.ok) throw new Error(await response.text());
            return await response.json();
          }
        }
      };
    </script>
    <script type="module">${js}</script>
  </body>
</html>`;
}

async function dashboardPayload(query: Record<string, string> = {}) {
  const { startDate, endDate } = normalizeQuery(query);
  const previous = previousWindow(startDate, endDate);
  const workspace =
    process.env.WM_WORKSPACE ||
    process.env.WORKSPACE ||
    process.env.WM_WORKSPACE_ID ||
    "beforest-automations";
  const sql = datatable(workspace);

  if (!(await tableExists(sql, "fb_ads_campaign_daily_metrics"))) {
    const totals = summarize([]);
    return {
      ok: true,
      ready: false,
      message: "Dashboard datatables do not exist yet. Run f/facebook_ads_dashboard/sync_facebook_ads_metrics once.",
      generated_at: new Date().toISOString(),
      window: { start_date: startDate, end_date: endDate, timezone: "Asia/Kolkata" },
      previous_window: previous,
      funnel: [
        { key: "reach", label: "Reach", value: 0, conversion_from_previous: 100, owner_hint: "Unique people reached by ads." },
        { key: "link_clicks", label: "Link Clicks", value: 0, conversion_from_previous: 0, owner_hint: "People clicking ad links." },
        { key: "website_visits", label: "Website Visits", value: 0, conversion_from_previous: 0, owner_hint: "Landing page views from ad traffic." },
        { key: "typeform_submits", label: "Typeform Submits", value: 0, conversion_from_previous: 0, owner_hint: "Meta pixel TypeformSubmit conversions." },
      ],
      totals,
      previous_totals: totals,
      deltas: {},
      daily: { typeform_submits: [], daily_cpl: [], reach: [], spend: [], link_clicks: [] },
      campaigns: [],
      creatives: [],
      top_creatives: [],
      creatives_to_review: [],
      community: {
        comments_checked: 0,
        answered_comments: 0,
        unanswered_count: 0,
        response_rate: 0,
        lead_intent_comments: 0,
        risk_comments: 0,
        top_creative_needing_replies: null,
        unanswered: [],
      },
      insights: [{ title: "Metrics are not synced", body: "Run f/facebook_ads_dashboard/sync_facebook_ads_metrics once, then refresh this link.", tone: "amber" }],
    };
  }

  const [campaignRowsRaw, previousCampaignRowsRaw, creativeRowsRaw, communitySnapshot] = await Promise.all([
    sql`
      SELECT *
      FROM fb_ads_campaign_daily_metrics
      WHERE metric_date >= ${startDate}::TEXT::DATE
        AND metric_date <= ${endDate}::TEXT::DATE
      ORDER BY metric_date ASC
    `.fetch(),
    sql`
      SELECT *
      FROM fb_ads_campaign_daily_metrics
      WHERE metric_date >= ${previous.start_date}::TEXT::DATE
        AND metric_date <= ${previous.end_date}::TEXT::DATE
      ORDER BY metric_date ASC
    `.fetch(),
    sql`
      SELECT
        d.*,
        COALESCE(m.creative_name, d.ad_name) AS creative_name,
        m.thumbnail_url,
        m.effective_object_story_id
      FROM fb_ads_creative_daily_metrics d
      LEFT JOIN fb_ads_creative_metadata m
        ON m.ad_id = d.ad_id
      WHERE d.metric_date >= ${startDate}::TEXT::DATE
        AND d.metric_date <= ${endDate}::TEXT::DATE
      ORDER BY d.metric_date ASC
    `.fetch(),
    sql`
      SELECT *
      FROM fb_ads_comment_response_snapshots
      WHERE snapshot_key = 'latest'
      LIMIT 1
    `.fetchOne(),
  ]);

  const campaignRows = campaignRowsRaw as DailyRow[];
  const previousCampaignRows = previousCampaignRowsRaw as DailyRow[];
  const creativeRows = creativeRowsRaw as Array<DailyRow & {
    ad_id: string;
    ad_name: string;
    campaign_id?: string;
    campaign_name?: string;
    creative_name?: string;
    thumbnail_url?: string;
  }>;

  const totals = summarize(campaignRows);
  const previousTotals = summarize(previousCampaignRows);
  const previousCampaignMap = new Map(
    [...groupBy(previousCampaignRows, (row) => row.campaign_id).entries()].map(([id, rows]) => [id, summarize(rows)]),
  );

  const campaigns = [...groupBy(campaignRows, (row) => row.campaign_id).entries()]
    .map(([campaign_id, rows]) => {
      const metrics = summarize(rows);
      return {
        campaign_id,
        campaign_name: rows[0]?.campaign_name || campaign_id,
        ...metrics,
        status: campaignStatus(metrics, previousCampaignMap.get(campaign_id), totals.cpl),
      };
    })
    .sort((a, b) => b.typeform_submits - a.typeform_submits || (a.cpl ?? Infinity) - (b.cpl ?? Infinity));

  const creatives = [...groupBy(creativeRows, (row) => row.ad_id).entries()]
    .map(([ad_id, rows]) => {
      const metrics = summarize(rows);
      return {
        ad_id,
        ad_name: rows[0]?.ad_name || ad_id,
        campaign_name: rows[0]?.campaign_name,
        creative_name: rows[0]?.creative_name || rows[0]?.ad_name || ad_id,
        thumbnail_url: rows[0]?.thumbnail_url,
        ...metrics,
      };
    })
    .sort((a, b) => b.typeform_submits - a.typeform_submits || (a.cpl ?? Infinity) - (b.cpl ?? Infinity));

  const avgCreativeSubmits = safeRate(
    creatives.reduce((sum, row) => sum + row.typeform_submits, 0),
    creatives.length,
  );
  const topCreatives = creatives.filter((row) => row.typeform_submits > 0).slice(0, 8);
  const creativesToReview = creatives
    .filter((row) => !(row.typeform_submits >= avgCreativeSubmits && row.cpl !== null && totals.cpl !== null && row.cpl <= totals.cpl))
    .filter((row) => (row.spend >= 500 && row.typeform_submits < avgCreativeSubmits && row.cpl !== null && totals.cpl !== null && row.cpl > totals.cpl) || row.ctr < totals.ctr * 0.65)
    .sort((a, b) => b.spend - a.spend || a.typeform_submits - b.typeform_submits || a.ctr - b.ctr)
    .slice(0, 8);

  const unanswered = Array.isArray(communitySnapshot?.unanswered_comments_json)
    ? communitySnapshot.unanswered_comments_json
    : [];

  return {
    ok: true,
    ready: true,
    generated_at: new Date().toISOString(),
    window: { start_date: startDate, end_date: endDate, timezone: "Asia/Kolkata" },
    previous_window: previous,
    funnel: [
      { key: "reach", label: "Reach", value: totals.reach, conversion_from_previous: 100, owner_hint: "Unique people reached by ads." },
      { key: "link_clicks", label: "Link Clicks", value: totals.link_clicks, conversion_from_previous: totals.click_rate * 100, owner_hint: "People clicking ad links." },
      { key: "website_visits", label: "Website Visits", value: totals.website_visits, conversion_from_previous: totals.website_visit_rate * 100, owner_hint: "Landing page views from ad traffic." },
      { key: "typeform_submits", label: "Typeform Submits", value: totals.typeform_submits, conversion_from_previous: totals.typeform_submit_rate * 100, owner_hint: "Meta pixel TypeformSubmit conversions." },
    ],
    totals,
    previous_totals: previousTotals,
    deltas: {
      spend: delta(totals.spend, previousTotals.spend, true),
      reach: delta(totals.reach, previousTotals.reach),
      link_clicks: delta(totals.link_clicks, previousTotals.link_clicks),
      website_visits: delta(totals.website_visits, previousTotals.website_visits),
      typeform_submits: delta(totals.typeform_submits, previousTotals.typeform_submits),
      ctr: delta(totals.ctr, previousTotals.ctr),
      cpl: delta(totals.cpl, previousTotals.cpl, true),
    },
    daily: {
      typeform_submits: dailySeries(campaignRows, "typeform_submits"),
      daily_cpl: dailySeries(campaignRows, "daily_cpl"),
      reach: dailySeries(campaignRows, "reach"),
      spend: dailySeries(campaignRows, "spend"),
      link_clicks: dailySeries(campaignRows, "link_clicks"),
    },
    campaigns,
    creatives,
    top_creatives: topCreatives,
    creatives_to_review: creativesToReview,
    community: {
      comments_checked: num(communitySnapshot?.comments_checked),
      answered_comments: num(communitySnapshot?.answered_comments),
      unanswered_count: num(communitySnapshot?.unanswered_count),
      response_rate: num(communitySnapshot?.response_rate),
      lead_intent_comments: num(communitySnapshot?.lead_intent_comments),
      risk_comments: num(communitySnapshot?.risk_comments),
      top_creative_needing_replies: communitySnapshot?.top_creative_name
        ? {
            creative_name: communitySnapshot.top_creative_name,
            unanswered_count: num(communitySnapshot.top_creative_unanswered_count),
          }
        : null,
      unanswered,
    },
    insights: buildInsights(totals, previousTotals),
  };
}

function renderDashboard(payload: Awaited<ReturnType<typeof dashboardPayload>>) {
  const totals = payload.totals;
  const previous = payload.previous_totals;
  const metrics = [
    ["Spend", money(totals.spend), delta(totals.spend, previous.spend, true)],
    ["Reach", integer(totals.reach), delta(totals.reach, previous.reach)],
    ["Link clicks", integer(totals.link_clicks), delta(totals.link_clicks, previous.link_clicks)],
    ["Website visits", integer(totals.website_visits), delta(totals.website_visits, previous.website_visits)],
    ["Typeform submits", integer(totals.typeform_submits), delta(totals.typeform_submits, previous.typeform_submits)],
    ["CPL", money(totals.cpl), delta(totals.cpl, previous.cpl, true)],
  ];

  const funnel = [
    ["Reach", totals.reach, "100%"],
    ["Link clicks", totals.link_clicks, pct(totals.click_rate)],
    ["Website visits", totals.website_visits, pct(totals.website_visit_rate)],
    ["Typeform submits", totals.typeform_submits, pct(totals.typeform_submit_rate)],
  ];

  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Beforest Facebook Ads Dashboard</title>
  <style>
    :root { color-scheme: light; --ink:#17201b; --muted:#66726c; --line:#dbe4df; --paper:#f7f4ec; --panel:#ffffff; --green:#146b4d; --amber:#a15d04; --bad:#ad2d2d; --blue:#315e94; }
    * { box-sizing: border-box; }
    body { margin: 0; font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; background: var(--paper); color: var(--ink); }
    .lock { min-height: 100vh; display: grid; place-items: center; padding: 24px; background: linear-gradient(135deg, #f7f4ec 0%, #edf5ef 55%, #f7f4ec 100%); }
    .lock-panel { width: min(420px, 100%); background: var(--panel); border: 1px solid var(--line); border-radius: 8px; padding: 28px; box-shadow: 0 22px 60px rgba(30, 45, 38, .13); }
    .lock-panel h1 { margin: 0 0 8px; font-size: 26px; letter-spacing: 0; }
    .lock-panel p { margin: 0 0 20px; color: var(--muted); line-height: 1.5; }
    label { display: block; color: var(--muted); font-size: 12px; font-weight: 700; text-transform: uppercase; margin-bottom: 8px; }
    input { width: 100%; min-height: 44px; border: 1px solid var(--line); border-radius: 6px; padding: 10px 12px; font: inherit; background: #fff; color: var(--ink); }
    button { min-height: 44px; border: 0; border-radius: 6px; padding: 10px 14px; font: inherit; font-weight: 700; color: #fff; background: var(--green); cursor: pointer; }
    .lock-actions { display: flex; gap: 10px; align-items: end; }
    .lock-actions div { flex: 1; }
    .error { min-height: 20px; margin-top: 10px; color: var(--bad); font-size: 13px; }
    .app { display: none; }
    body.unlocked .lock { display: none; }
    body.unlocked .app { display: block; }
    header { background: #10241c; color: #fff; padding: 28px 24px; }
    .wrap { width: min(1180px, calc(100% - 32px)); margin: 0 auto; }
    .topbar { display: flex; gap: 16px; justify-content: space-between; align-items: start; flex-wrap: wrap; }
    h1 { margin: 0; font-size: clamp(28px, 4vw, 42px); letter-spacing: 0; }
    .sub { margin: 8px 0 0; color: #c9d9d1; }
    .date-form { display: flex; gap: 10px; align-items: end; flex-wrap: wrap; background: rgba(255,255,255,.08); border: 1px solid rgba(255,255,255,.12); border-radius: 8px; padding: 12px; }
    .date-form label { color: #c9d9d1; }
    .date-form input { width: 150px; min-height: 38px; }
    .date-form button { min-height: 38px; background: #f1c866; color: #17201b; }
    main { padding: 24px 0 44px; }
    .grid { display: grid; gap: 14px; }
    .metrics { grid-template-columns: repeat(6, minmax(0, 1fr)); }
    .card, .panel { background: var(--panel); border: 1px solid var(--line); border-radius: 8px; }
    .card { padding: 16px; min-height: 116px; }
    .card span { color: var(--muted); font-size: 13px; font-weight: 700; }
    .card strong { display: block; margin: 12px 0 6px; font-size: 26px; letter-spacing: 0; }
    .good { color: var(--green); }
    .bad { color: var(--bad); }
    .muted { color: var(--muted); }
    .two { grid-template-columns: 1.1fr .9fr; margin-top: 14px; }
    .panel { padding: 18px; overflow: hidden; }
    .panel h2 { margin: 0 0 14px; font-size: 18px; letter-spacing: 0; }
    .funnel { display: grid; gap: 10px; }
    .funnel-row { display: grid; grid-template-columns: 150px 1fr 70px; gap: 12px; align-items: center; }
    .bar { height: 12px; background: #edf2ef; border-radius: 999px; overflow: hidden; }
    .fill { height: 100%; background: var(--green); border-radius: inherit; }
    .insights { display: grid; gap: 10px; }
    .insight { border-left: 4px solid var(--green); padding: 10px 12px; background: #f7faf8; border-radius: 6px; }
    .insight.amber { border-color: var(--amber); }
    .insight.pink { border-color: var(--bad); }
    .insight.blue { border-color: var(--blue); }
    .insight strong { display: block; margin-bottom: 4px; }
    .table-wrap { overflow-x: auto; }
    table { width: 100%; border-collapse: collapse; font-size: 14px; }
    th, td { padding: 12px 10px; border-bottom: 1px solid var(--line); text-align: left; white-space: nowrap; }
    th { color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: 0; }
    td.name { min-width: 260px; white-space: normal; font-weight: 700; }
    .pill { display: inline-flex; min-width: 70px; justify-content: center; border-radius: 999px; padding: 4px 8px; font-size: 12px; font-weight: 800; background: #edf2ef; color: var(--muted); }
    .pill.scale { background: #dff2e8; color: var(--green); }
    .pill.weak, .pill.fatigue { background: #f7e3dd; color: var(--bad); }
    .pill.watch { background: #faedd6; color: var(--amber); }
    .section { margin-top: 14px; }
    .creative { display: grid; grid-template-columns: 54px 1fr; gap: 12px; align-items: center; min-width: 280px; }
    .creative img { width: 54px; height: 54px; object-fit: cover; border-radius: 6px; background: #edf2ef; }
    .comment-list { display: grid; gap: 10px; }
    .comment { padding: 12px; border: 1px solid var(--line); border-radius: 8px; background: #fbfcfb; }
    .comment b { display: block; margin-bottom: 4px; }
    footer { margin-top: 18px; color: var(--muted); font-size: 12px; }
    @media (max-width: 980px) { .metrics, .two { grid-template-columns: 1fr 1fr; } }
    @media (max-width: 640px) { .metrics, .two { grid-template-columns: 1fr; } .topbar, .date-form { display: block; } .date-form input, .date-form button { width: 100%; margin-top: 8px; } .funnel-row { grid-template-columns: 1fr; gap: 6px; } }
  </style>
</head>
<body>
  <section class="lock" aria-label="Dashboard passcode gate">
    <form class="lock-panel" id="lock-form">
      <h1>Beforest Facebook Ads</h1>
      <p>Enter the team passcode to open the live ads growth and comment health dashboard.</p>
      <div class="lock-actions">
        <div>
          <label for="dashboard-passcode">Passcode</label>
          <input id="dashboard-passcode" type="password" autocomplete="current-password">
        </div>
        <button type="submit">Open</button>
      </div>
      <div class="error" id="passcode-error"></div>
    </form>
  </section>
  <div class="app">
    <header>
      <div class="wrap topbar">
        <div>
          <h1>Beforest Facebook Ads</h1>
          <p class="sub">${escapeHtml(payload.window.start_date)} to ${escapeHtml(payload.window.end_date)}. Refreshed ${escapeHtml(new Date(payload.generated_at).toLocaleString("en-IN", { timeZone: "Asia/Kolkata" }))} IST.</p>
        </div>
        <form class="date-form" method="get">
          <div><label for="start_date">Start</label><input id="start_date" name="start_date" type="date" value="${escapeHtml(payload.window.start_date)}"></div>
          <div><label for="end_date">End</label><input id="end_date" name="end_date" type="date" value="${escapeHtml(payload.window.end_date)}"></div>
          <button type="submit">Refresh</button>
        </form>
      </div>
    </header>
    <main class="wrap">
      <section class="grid metrics">
        ${metrics.map(([label, value, change]) => `<article class="card"><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong><small class="${(change as any).className}">${escapeHtml((change as any).text)} vs previous window</small></article>`).join("")}
      </section>

      <section class="grid two">
        <article class="panel">
          <h2>Funnel</h2>
          <div class="funnel">
            ${funnel.map(([label, value, conversion], index) => {
              const max = Math.max(1, Number(funnel[0][1]));
              const width = index === 0 ? 100 : Math.max(4, Math.min(100, safeRate(Number(value), max) * 100));
              return `<div class="funnel-row"><strong>${escapeHtml(label)}: ${integer(Number(value))}</strong><div class="bar"><div class="fill" style="width:${width}%"></div></div><span>${escapeHtml(conversion)}</span></div>`;
            }).join("")}
          </div>
        </article>
        <article class="panel">
          <h2>Signals</h2>
          <div class="insights">
            ${payload.insights.map((item) => `<div class="insight ${escapeHtml(item.tone)}"><strong>${escapeHtml(item.title)}</strong><span>${escapeHtml(item.body)}</span></div>`).join("")}
          </div>
        </article>
      </section>

      <section class="panel section">
        <h2>Campaigns</h2>
        <div class="table-wrap">
          <table>
            <thead><tr><th>Campaign</th><th>Status</th><th>Spend</th><th>Reach</th><th>Clicks</th><th>Visits</th><th>Submits</th><th>CTR</th><th>CPL</th></tr></thead>
            <tbody>
              ${payload.campaigns.slice(0, 20).map((row: any) => `<tr><td class="name">${escapeHtml(row.campaign_name)}</td><td><span class="pill ${statusClass(row.status)}">${escapeHtml(row.status)}</span></td><td>${money(row.spend)}</td><td>${integer(row.reach)}</td><td>${integer(row.link_clicks)}</td><td>${integer(row.website_visits)}</td><td>${integer(row.typeform_submits)}</td><td>${pct(row.ctr)}</td><td>${money(row.cpl)}</td></tr>`).join("")}
            </tbody>
          </table>
        </div>
      </section>

      <section class="panel section">
        <h2>Top Creatives</h2>
        <div class="table-wrap">
          <table>
            <thead><tr><th>Creative</th><th>Campaign</th><th>Spend</th><th>Reach</th><th>Clicks</th><th>Submits</th><th>CTR</th><th>CPL</th><th>Shares</th><th>Comments</th></tr></thead>
            <tbody>
              ${payload.creatives.slice(0, 12).map((row: any) => `<tr><td><div class="creative">${row.thumbnail_url ? `<img src="${escapeHtml(row.thumbnail_url)}" alt="">` : `<img alt="">`}<strong>${escapeHtml(row.creative_name)}</strong></div></td><td>${escapeHtml(row.campaign_name)}</td><td>${money(row.spend)}</td><td>${integer(row.reach)}</td><td>${integer(row.link_clicks)}</td><td>${integer(row.typeform_submits)}</td><td>${pct(row.ctr)}</td><td>${money(row.cpl)}</td><td>${integer(row.shares)}</td><td>${integer(row.comments)}</td></tr>`).join("")}
            </tbody>
          </table>
        </div>
      </section>

      <section class="grid two section">
        <article class="panel">
          <h2>Comment Health</h2>
          ${payload.community ? `<div class="grid metrics" style="grid-template-columns: repeat(3, minmax(0, 1fr));"><div><strong>${integer(payload.community.comments_checked)}</strong><br><span class="muted">Checked</span></div><div><strong>${integer(payload.community.unanswered_count)}</strong><br><span class="muted">Unanswered</span></div><div><strong>${pct(payload.community.response_rate)}</strong><br><span class="muted">Response rate</span></div></div><p class="muted">Lead-intent: ${integer(payload.community.lead_intent_comments)}. Risk comments: ${integer(payload.community.risk_comments)}.</p>` : `<p class="muted">No community snapshot yet.</p>`}
        </article>
        <article class="panel">
          <h2>Unanswered Queue</h2>
          <div class="comment-list">
            ${payload.community?.unanswered?.length ? payload.community.unanswered.map((row: any) => `<div class="comment"><b>${escapeHtml(row.from_name || row.username || "Comment")}</b><span>${escapeHtml(row.message || row.text || "")}</span></div>`).join("") : `<p class="muted">No unanswered comments in the latest snapshot.</p>`}
          </div>
        </article>
      </section>
      <footer>Public route served from f/facebook_ads_dashboard/serve_facebook_ads_dashboard.</footer>
    </main>
  </div>
  <script>
    const PASSCODE = ${JSON.stringify(DASHBOARD_PASSCODE)};
    const form = document.getElementById('lock-form');
    const input = document.getElementById('dashboard-passcode');
    const error = document.getElementById('passcode-error');
    function unlock() { document.body.classList.add('unlocked'); }
    if (localStorage.getItem('beforest_fb_dashboard_unlocked') === 'true') unlock();
    form.addEventListener('submit', (event) => {
      event.preventDefault();
      if (input.value.trim() === PASSCODE) {
        localStorage.setItem('beforest_fb_dashboard_unlocked', 'true');
        unlock();
      } else {
        error.textContent = 'That passcode is not matching.';
      }
    });
  </script>
</body>
</html>`;
}

export async function preprocessor(event: { kind: string; query?: Record<string, string> }) {
  if (event.kind === "http") return { query: event.query || {} };
  return { query: {} };
}

export async function main(query: Record<string, string> = {}) {
  if (query[RAW_APP_API_PARAM] === "fetch_dashboard") {
    return {
      windmill_content_type: "application/json; charset=utf-8",
      result: await dashboardPayload(query),
    };
  }

  return {
    windmill_content_type: "text/html; charset=utf-8",
    result: renderRawAppHtml(),
  };
}
